<script setup lang="ts">
import type { ApiEnvelope } from '~/types/api'
import type { Customer, StaffRole } from '~/types/billing'
import { billingDate } from '~/utils/billing'
definePageMeta({ layout:'admin', middleware:'management' })
const { request } = useApi()
const { rows, pagination, pending, error, refresh, search, status, role, page, message, failure, saving, mutate } = await useManagement<Customer>('staff')
const { data:access, error:roleError, refresh:refreshRoles } = await useAsyncData('staff-role-definitions', () => request<ApiEnvelope<{roles:StaffRole[];permissions:Record<string,string>}>>('management/roles'))
const tab = ref<'users'|'roles'>('users'), query = ref(''), accountOpen = ref(false), selected = ref<Customer|null>(null), roleOpen = ref(false), selectedRole = ref<StaffRole|null>(null)
const form = reactive({ name:'', email:'', role:'user', status:'active' })
const roleForm = reactive({ name:'', slug:'', is_active:true, permissions:[] as string[] })
const availableRoles = computed(() => access.value?.data.roles.filter(item => item.is_active) || [])
const roleName = (slug:string) => slug==='superadmin'?'Superadmin':access.value?.data.roles.find(item=>item.slug===slug)?.name || slug
function edit(user?:Customer) { selected.value=user || null; Object.assign(form,{name:user?.name || '',email:user?.email || '',role:user?.role || 'user',status:user?.status || 'active'}); failure.value='';accountOpen.value=true }
async function saveAccount() { const body=selected.value?{name:form.name,role:form.role,status:form.status}:{name:form.name,email:form.email,role:form.role}; if(await mutate(`management/staff${selected.value?`/${selected.value.id}`:''}`,body,selected.value?'PATCH':'POST')) {accountOpen.value=false;await refreshRoles()} }
function editRole(item?:StaffRole) { selectedRole.value=item || null; Object.assign(roleForm,{name:item?.name || '',slug:item?.slug || '',is_active:item?.is_active ?? true,permissions:[...(item?.permissions || [])]}); failure.value='';roleOpen.value=true }
async function saveRole() { if(await mutate(`management/roles${selectedRole.value?`/${selectedRole.value.id}`:''}`,roleForm,selectedRole.value?'PUT':'POST')){roleOpen.value=false;await refreshRoles()} }
</script>
<template><div><div class="flex flex-wrap justify-between gap-4"><div><p class="eyebrow">Access administration</p><h1 class="page-title mt-2">Users & roles</h1><p class="mt-2 text-text-secondary">Invite colleagues, assign responsibilities, and control who can do what.</p></div><button v-if="tab==='users'" class="btn-primary" @click="edit()">+ Add user</button><button v-else class="btn-primary" @click="editRole()">+ Create role</button></div><div class="mt-6 flex gap-6 border-b border-border" role="tablist" aria-label="Access management"><button id="users-tab" class="border-b-2 px-1 pb-3 text-sm font-medium" :class="tab==='users'?'border-brand text-brand':'border-transparent text-text-muted'" role="tab" aria-controls="users-panel" :aria-selected="tab==='users'" @click="tab='users'">Users</button><button id="roles-tab" class="border-b-2 px-1 pb-3 text-sm font-medium" :class="tab==='roles'?'border-brand text-brand':'border-transparent text-text-muted'" role="tab" aria-controls="roles-panel" :aria-selected="tab==='roles'" @click="tab='roles'">Roles & permissions</button></div><p v-if="message" class="mt-5 rounded-lg bg-success-bg p-4 text-success" role="status">{{ message }}</p><p v-if="failure && !accountOpen && !roleOpen" class="mt-5 text-danger" role="alert">{{ failure }}</p><div v-if="tab==='users'" id="users-panel" role="tabpanel" aria-labelledby="users-tab"><form class="my-6 flex flex-wrap gap-3" @submit.prevent="search=query;page=1"><input v-model="query" class="input max-w-sm" aria-label="Search users" placeholder="Search name or email"><select v-model="role" class="input w-auto" aria-label="Filter by role" @change="page=1"><option value="">All roles</option><option value="superadmin">Superadmin</option><option v-for="item in access?.data.roles" :key="item.id" :value="item.slug">{{ item.name }}</option></select><select v-model="status" class="input w-auto" aria-label="Filter account status" @change="page=1"><option value="">All statuses</option><option value="active">Active</option><option value="suspended">Suspended</option></select><button class="btn-secondary">Search</button></form><div class="surface overflow-hidden"><LoadingState v-if="pending"/><p v-else-if="error" class="p-6" role="alert">Unable to load users. <button class="text-brand" @click="refresh()">Retry</button></p><div v-else class="overflow-x-auto"><table class="admin-table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Email</th><th>Joined</th><th>Action</th></tr></thead><tbody><tr v-for="user in rows" :key="user.id"><td><p class="font-medium">{{ user.name }}</p><p class="text-xs text-text-muted">{{ user.email }}</p></td><td><span class="badge-brand">{{ roleName(user.role) }}</span></td><td><span :class="user.status==='active'?'badge-success':'badge-danger'">{{ user.status }}</span></td><td>{{ user.email_verified_at?'Verified':'Verification pending' }}</td><td>{{ billingDate(user.created_at) }}</td><td><span v-if="user.role==='superadmin'" class="text-xs text-text-muted">Protected account</span><button v-else class="text-brand" @click="edit(user)">Manage access</button></td></tr><tr v-if="!rows.length"><td colspan="6" class="py-12 text-center">No users match these filters.</td></tr></tbody></table></div><AdminPagination v-if="pagination" :current="pagination.current_page" :last="pagination.last_page" :total="pagination.total" :pending="pending" @change="page=$event"/></div></div><div v-else id="roles-panel" role="tabpanel" aria-labelledby="roles-tab"><p class="mt-6 text-sm text-text-secondary">Superadmin access is protected and cannot be assigned through these forms. Permissions apply to all users assigned to a role.</p><p v-if="roleError" class="mt-5 text-danger" role="alert">Roles could not be loaded. <button @click="refreshRoles()">Retry</button></p><div class="mt-6 grid gap-5 lg:grid-cols-3"><article v-for="item in access?.data.roles" :key="item.id" class="surface flex flex-col p-6"><div class="flex justify-between gap-3"><h2 class="text-lg font-semibold">{{ item.name }}</h2><span :class="item.is_active?'badge-success':'badge-warning'">{{ item.is_active?'Active':'Disabled' }}</span></div><p class="mt-2 text-xs text-text-muted">{{ item.users_count }} assigned users · {{ item.is_system?'Built-in role':'Custom role' }}</p><ul class="my-5 flex-1 space-y-2 text-xs text-text-secondary"><li v-for="permission in item.permissions" :key="permission">✓ {{ access?.data.permissions[permission] || permission }}</li><li v-if="!item.permissions.length">Customer workspace only</li></ul><button v-if="item.slug!=='user'" class="btn-secondary" @click="editRole(item)">Edit permissions</button><p v-else class="text-xs text-text-muted">The customer role is protected.</p></article></div></div><AdminDialog v-if="accountOpen" :title="selected?'Manage user access':'Add a user'" @close="accountOpen=false"><form class="grid gap-4" @submit.prevent="saveAccount"><label class="label">Full name<input v-model="form.name" class="input mt-2" maxlength="120" required></label><label class="label">Email address<input v-model="form.email" class="input mt-2" type="email" :disabled="Boolean(selected)" required></label><label class="label">Assigned role<select v-model="form.role" class="input mt-2" required><option v-for="item in availableRoles" :key="item.id" :value="item.slug">{{ item.name }}</option></select></label><label v-if="selected" class="label">Account status<select v-model="form.status" class="input mt-2"><option value="active">Active</option><option value="suspended">Suspended</option></select></label><p class="rounded-lg bg-surface2 p-4 text-xs text-text-secondary">{{ selected?'Changing a role or status revokes existing sessions. The user must sign in again.':'A verification email and a password setup email will be sent. Staff must verify their email before accessing administration. No default password is created.' }}</p><p v-if="message && selected" class="text-sm text-success" role="status">{{ message }}</p><p v-if="failure" class="text-sm text-danger" role="alert">{{ failure }}</p><div class="flex flex-wrap justify-between gap-3"><button v-if="selected" type="button" class="btn-secondary" :disabled="saving || form.status!=='active'" @click="mutate(`management/staff/${selected.id}/setup`)">Send setup emails</button><button class="btn-primary" :disabled="saving">{{ saving?'Saving…':selected?'Save access':'Create user & send setup' }}</button></div></form></AdminDialog><AdminDialog v-if="roleOpen" :title="selectedRole?'Edit role permissions':'Create a custom role'" @close="roleOpen=false"><form class="grid gap-4" @submit.prevent="saveRole"><label class="label">Role name<input v-model="roleForm.name" class="input mt-2" maxlength="100" required></label><label class="label">Role identifier<input v-model="roleForm.slug" class="input mt-2" maxlength="24" pattern="[a-z][a-z0-9_-]{1,23}" :disabled="Boolean(selectedRole)" placeholder="operations" required></label><fieldset class="space-y-3 rounded-lg border border-border p-4"><legend class="px-1 text-sm font-medium">Allowed actions</legend><label v-for="(label,permission) in access?.data.permissions" :key="permission" class="flex items-start gap-3 text-sm"><input v-model="roleForm.permissions" :value="permission" type="checkbox" class="mt-1 accent-brand"><span>{{ label }}</span></label></fieldset><label class="flex gap-3 text-sm"><input v-model="roleForm.is_active" type="checkbox">Role enabled</label><p class="text-xs text-text-muted">Saving revokes existing sessions for assigned users. Write actions include the read access needed to use them. Disabling a role removes its administrative access without deleting users or records.</p><p v-if="failure" class="text-sm text-danger" role="alert">{{ failure }}</p><button class="btn-primary" :disabled="saving">{{ saving?'Saving…':'Save role' }}</button></form></AdminDialog></div></template>
